<?php
declare(strict_types=1);
require_once __DIR__ . '/../shared/response.php'; require_once __DIR__ . '/../shared/request.php'; require_once __DIR__ . '/../shared/auth.php';
methodOnly('DELETE'); requireAdmin(); safeApi(function (): void { $db=apiDatabase(); $id=requestId(); $db->beginTransaction(); $check=$db->prepare('SELECT id FROM products WHERE id=:id FOR UPDATE');$check->execute([':id'=>$id]);if(!$check->fetch()){$db->rollBack();jsonResponse(false,'Product not found.',null,[],404);} if(tableExistsForDelete($db,'order_items')){$orders=$db->prepare('SELECT COUNT(*) FROM order_items WHERE product_id=:id');$orders->execute([':id'=>$id]);if((int)$orders->fetchColumn()>0){$db->rollBack();jsonResponse(false,'This product is linked to existing orders and cannot be deleted.',null,[],409);}}$paths=[];if(tableExistsForDelete($db,'product_images')){$q=$db->prepare('SELECT image_path FROM product_images WHERE product_id=:id');$q->execute([':id'=>$id]);$paths=array_column($q->fetchAll(),'image_path');$db->prepare('DELETE FROM product_images WHERE product_id=:id')->execute([':id'=>$id]);}if(tableExistsForDelete($db,'product_variations'))$db->prepare('DELETE FROM product_variations WHERE product_id=:id')->execute([':id'=>$id]);$statement=$db->prepare('DELETE FROM products WHERE id=:id');$statement->execute([':id'=>$id]);if($statement->rowCount()!==1){$db->rollBack();jsonResponse(false,'Product could not be deleted.',null,[],500);}$db->commit();foreach($paths as $path){$file=__DIR__.'/../../'.ltrim((string)$path,'/');if(is_file($file)&&strpos(realpath($file),realpath(__DIR__.'/../../uploads/'))===0)@unlink($file);}jsonResponse(true,'Product deleted successfully.'); });
function tableExistsForDelete(PDO $db,string $table):bool{$q=$db->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:table');$q->execute([':table'=>$table]);return (bool)$q->fetchColumn();}
